use std :: path :: { Path , PathBuf } ; use std :: sync :: Arc ; use anyhow :: Context ; use forge_app :: domain :: Skill ; use forge_app :: { EnvironmentInfra , FileInfoInfra , FileReaderInfra , Walker , WalkerInfra } ; use forge_domain :: SkillRepository ; use futures :: future :: join_all ; use gray_matter :: Matter ; use gray_matter :: engine :: YAML ; use serde :: Deserialize ; use forge_config :: ForgeConfig ; use forge_infra :: ForgeInfra ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Repository implementation for loading skills from multiple sources:"] # [doc = " 1. Built-in skills (embedded in the application)"] # [doc = " 2. Global custom skills (from ~/forge/skills/ directory)"] # [doc = " 3. Agents skills (from ~/.agents/skills/ directory)"] # [doc = " 4. Project-local skills (from .forge/skills/ directory in current working"] # [doc = "    directory)"] # [doc = ""] # [doc = " ## Skill Precedence"] # [doc = " When skills have duplicate names across different sources, the precedence"] # [doc = " order is: **CWD (project-local) > Agents (~/.agents/skills) > Global"] # [doc = " custom > Built-in**"] # [doc = ""] # [doc = " This means project-local skills can override agents skills, which can"] # [doc = " override global skills, which can override built-in skills."] # [doc = ""] # [doc = " ## Directory Resolution"] # [doc = " - **Built-in skills**: Embedded in application binary"] # [doc = " - **Global skills**: `~/forge/skills/<skill-name>/SKILL.md`"] # [doc = " - **Agents skills**: `~/.agents/skills/<skill-name>/SKILL.md`"] # [doc = " - **CWD skills**: `./.forge/skills/<skill-name>/SKILL.md` (relative to"] # [doc = "   current working directory)"] # [doc = ""] # [doc = " Missing directories are handled gracefully and don't prevent loading from"] # [doc = " other sources."] pub struct ForgeSkillRepository < I > { infra : Arc < I > , }